function buildDuskArtUri(pal) {
  const svg = DUSK_ART_SVG
    .replace(/__DUSK_SKY_TOP__/g, rgbTriple(shadeHex(pal.cardBar, -75)))
    .replace(/__DUSK_SKY_MID1__/g, rgbTriple(shadeHex(pal.cardBar, -35)))
    .replace(/__DUSK_SKY_MID2__/g, rgbTriple(shadeHex(pal.cardAccent, -15)))
    .replace(/__DUSK_SKY_BOTTOM__/g, rgbTriple(shadeHex(pal.cardAccent, 10)))
    .replace(/__DUSK_GLOW__/g, rgbTriple(pal.cardAccent))
    .replace(/__DUSK_MOON_1__/g, rgbTriple(shadeHex(pal.cardAccent, 35)))
    .replace(/__DUSK_MOON_2__/g, rgbTriple(shadeHex(pal.cardAccent, 5)))
    .replace(/__DUSK_MOON_3__/g, rgbTriple(shadeHex(pal.cardAccent, -15)))
    .replace(/__DUSK_MOON_4__/g, rgbTriple(shadeHex(pal.cardAccent, -35)))
    .replace(/__DUSK_HILL_1__/g, rgbTriple(shadeHex(pal.cardAccent, -55)))
    .replace(/__DUSK_HILL_2__/g, rgbTriple(shadeHex(pal.cardAccent, -75)))
    .replace(/__DUSK_HILL_3__/g, rgbTriple(shadeHex(pal.cardAccent, -90)));
  return "data:image/svg+xml;base64," + btoa(svg);
}
function renderDusk() {
  const pal = getPalette(), dt = getDocType();
  const varStyle = `--dk-primary:${pal.cardBar};--dk-secondary:${pal.cardAccent};--dk-glow:${hexToRgba(pal.cardAccent, .55)};--dk-glow-soft:${hexToRgba(pal.cardAccent, .22)};`;
  const duskArtUri = buildDuskArtUri(pal);
  const hasLogo = !!state.logoDataUrl;
  const logo = hasLogo
    ? `<img src="${state.logoDataUrl}" alt="Institution logo">`
    : `<div class="dk-header-logo-mark"><i class="fa-solid fa-mountain-sun" aria-hidden="true"></i></div>`;
  const byName = or(state.byName || state.studentName, "—"), byId = or(state.byId || state.studentId, "—");
  const teacherName = or(state.toName, "—");
  const teacherDesigHtml = teacherInfoLines().map(esc).join("<br>") || "—";
  const isGroup = isGroupDoc();
  const byColInner = isGroup
    ? groupMembersDuskRowsHtml()
    : `<div class="dk-by-name">${esc(byName)}</div>
        <div class="dk-by-line"><b>${esc(t('id'))} : </b> ${esc(byId)}</div>
        <div class="dk-by-line"><b>${esc(t('roll'))} : </b> ${esc(or(state.roll, "—"))}</div>
        <div class="dk-by-line"><b>${esc(t('batch'))} : </b> ${esc(or(state.section, "—"))}</div>
        <div class="dk-by-line"><b>${esc(t('semester'))} : </b> ${esc(or(state.semester, "—"))}</div>`;
  const dkNoRaw = (state.assignmentNo || "").trim();
  const dkIsLabReport = isLabReportType();
  const dkNoVal = dkNoRaw
    ? (dkIsLabReport ? docNoOnly(dt) : stripNonDigits(dkNoRaw))
    : "";
  const dkIsNumeric = isAllDigits(dkNoVal);
  const dkEyebrowHtml = (dkIsLabReport && dkNoVal && !dkIsNumeric)
    ? `<span>${esc(dkNoVal)}</span>`
    : `<span>${esc(dt.word)}</span><span>${dkNoVal ? "- " + esc(dkNoVal) : ""}</span>`;
  return `<div class="tpl-dusk" style="${varStyle}">
    <img class="dk-artwork" src="${duskArtUri}" alt="" aria-hidden="true">
    <aside class="dk-panel" aria-hidden="true">
      <div class="dk-panel-top">
        <div class="dk-panel-word">${esc(dt.word)}</div>
        <div class="dk-panel-rule"></div>
      </div>
      <div class="dk-panel-bottom">
        <div class="dk-panel-name">${esc(isGroup ? groupTitleLabel() : or(state.studentName, t('studentNamePlaceholder')))}</div>
        <div class="dk-panel-meta">${esc(isGroup ? [groupCountLabel(), (state.section || '').trim(), (state.semester || '').trim() ? t('semAbbrevLabel') + ' ' + state.semester.trim() : ''].filter(Boolean).join(' | ') : or(state.studentId, t('studentRegId')))}</div>
      </div>
    </aside>
    <div class="dk-content">
      <header class="dk-header">
        <div class="dk-header-logo${hasLogo ? ' has-image' : ''}">${logo}</div>
        <div class="dk-header-text">
          <div class="dk-uni">${esc(or(state.universityName, t('universityNameFallback')))}</div>
          <div class="dk-dept">${esc(or(state.deptTitle, t('departmentFallback')))}</div>
        </div>
      </header>
      <section class="dk-title-block">
        <div class="dk-eyebrow">${dkEyebrowHtml}</div>
        <h1 class="dk-title">${esc(or(state.assignmentTitle, tf('titleGoesHere', { word: dt.word })))}</h1>
        <div class="dk-course">
          <span><b>${esc(t('course'))}</b> ${esc(or(state.courseTitle, "—"))}</span>
          <span><b>${esc(t('codeLabel'))}</b> ${esc(or(state.courseCode, "—"))}</span>
          ${state.dateExperiment ? `<span><b>${esc(t('dateOfExp'))}</b> ${esc(fmtDate(state.dateExperiment))}</span>` : ''}
        </div>
      </section>
      <section class="dk-info${isGroup ? ' is-group' : ''}">
        <div class="dk-info-col dk-info-by">
          <div class="dk-info-heading">${esc(t('submittedBy'))}</div>
          ${byColInner}
        </div>
        <div class="dk-info-col dk-info-to">
          <div class="dk-info-heading">${esc(t('submittedTo'))}</div>
          <div class="dk-to-name">${esc(teacherName)}</div>
          <div class="dk-to-desig">${teacherDesigHtml}</div>
        </div>
      </section>
      <footer class="dk-footer">
        <div class="dk-date-block">
          <span class="dk-date-label">${esc(t('dateOfSubmission'))}</span>
          <span class="dk-date-value">${esc(fmtDate(state.dateSubmission) || "—")}</span>
        </div>
        <div class="dk-footer-label"><span>${esc(t('signatureLabel'))}</span></div>
      </footer>
    </div>
  </div>`;
}
