// Chancery ("formal"): centered classic cover — logo, institution, doc-type
// eyebrow, big title, course, section/semester strip, then Submitted By /
// Submitted To columns and the submission date pinned to the foot.
// Assignment, Lab Report and Group Assignment all share this one layout:
//   lab   -> adds "Date of Experiment" to the section/semester strip
//   group -> Submitted By becomes the group name + a leader-first roster
// Chancery shows the department in short form (CSE / EEE / BBA) when it is one
// of the popular departments that have a known abbreviation. Less popular
// departments (e.g. "Civil Engineering (CE)"), one-word departments (Law,
// Pharmacy...) and Bangla names are shown exactly as entered.
function formalDeptDisplay(dept) {
  const raw = String(dept || '').trim();
  if (!raw) return '';
  if (/[\u0980-\u09FF]/.test(raw)) return raw;
  const keys = Object.keys(SUBJECTS_BY_DEPT);
  const ci = (a, b) => String(a).toLowerCase() === String(b).toLowerCase();
  const isPopular = k => !!DEPT_FULL_NAMES[k];
  if (!/\s/.test(raw)) {
    const k = keys.find(k => isPopular(k) && ci(k, raw));
    return k || raw;
  }
  const stripped = raw
    .replace(/^(department|dept)\.?\s+of\s+/i, '')
    .replace(/\s+(department|dept)\.?$/i, '')
    .trim();
  const paren = stripped.match(/\(([^)]+)\)\s*$/);
  if (paren) {
    const k = keys.find(k => isPopular(k) && ci(k, paren[1].trim()));
    if (k) return k;
  }
  const norm = v => String(v).toLowerCase().replace(/&/g, ' and ').replace(/[^a-z0-9]+/g, ' ').trim();
  const nameOnly = norm(stripped.replace(/\s*\([^)]*\)\s*$/, ''));
  const k = keys.find(k => isPopular(k) && norm(DEPT_FULL_NAMES[k]) === nameOnly);
  return k || raw;
}
function renderFormal() {
  const pal = getPalette();
  const dt = getDocType();
  const accent = safeHex(pal.cardBar, '#1e5993');
  const isLab = state.docType === 'lab';
  const isGroup = isGroupDoc();
  const isBn = state.language === 'bn';
  const byName = or(state.byName || state.studentName, '');
  const byId = or(state.byId || state.studentId, '');
  const toName = or(state.toName, '');
  const uniDisp = String(or(state.universityName, t('universityNameFallback')));
  const noRaw = (state.assignmentNo || '').trim();
  const has = v => v != null && String(v).trim() !== '';

  const logoHtml = state.logoDataUrl
    ? `<div class="fm-logo"><img class="fm-logo-img" src="${state.logoDataUrl}" alt="Institution logo"></div>` : '';
  const uniCls = uniDisp.length > 52 ? ' fm-uni-sm' : (uniDisp.length > 34 ? ' fm-uni-md' : '');

  // Eyebrow: "<DOC TYPE> / No. 01"
  const eyebrow = `${esc(dt.word)}${noRaw ? ` ${esc(t('fmNoShort') )} ${esc(noRaw)}` : ''}`;

  // Title (placeholder when empty)
  const titleRaw = (state.assignmentTitle || '').trim();
  const titleText = titleRaw || tf('titleGoesHere', { word: dt.word });
  const titleCls = (titleRaw ? '' : ' fm-ph') + (titleText.length > 110 ? ' fm-title-sm' : (titleText.length > 64 ? ' fm-title-md' : ''));

  // Course: "CODE : Title"
  const code = (state.courseCode || '').trim();
  const ctitle = (state.courseTitle || '').trim();
  const courseVal = (code || ctitle)
    ? `${code ? esc(code) : ''}${code && ctitle ? '<span class="fm-course-sep">:</span>' : ''}${ctitle ? esc(ctitle) : ''}`
    : `<span class="fm-ph">${esc(t('coverCourseTitleFallback'))}</span>`;

  // Section / semester (+ experiment date on lab reports)
  const metaItem = (label, val) => has(val)
    ? `<div class="fm-meta-item"><div class="fm-lbl">${esc(label)}</div><div class="fm-val">${esc(val)}</div></div>` : '';
  const expDate = isLab ? (fmtDate(state.dateExperiment) || '') : '';
  const metaHtml = [
    metaItem(t('fmSectionBatch'), state.section),
    metaItem(t('fmSemesterLabel'), state.semester),
    metaItem(t('dateOfExperimentLabel'), expDate)
  ].join('');

  const kv = (k, v) => has(v)
    ? `<div class="fm-kv"><span class="fm-k">${esc(k)}:</span><span class="fm-v">${esc(v)}</span></div>` : '';

  // Submitted By
  let byHead, byBody;
  if (isGroup) {
    const members = groupMembersLeaderFirst();
    const starHtml = `<svg class="fm-star" viewBox="0 0 24 24" role="img" aria-label="${esc(t('gmLeaderLabel'))}"><path d="M12.00 1.20 L15.47 7.83 L22.84 9.08 L17.61 14.42 L18.70 21.82 L12.00 18.50 L5.30 21.82 L6.39 14.42 L1.16 9.08 L8.53 7.83Z" fill="currentColor"/></svg>`;
    const rosterHtml = members.length ? members.map((m, i) => {
      const sub = [
        has(m.studentId) ? esc(t('id')) + ': ' + esc(m.studentId) : '',
        has(m.roll) ? esc(t('roll')) + ': ' + esc(m.roll) : ''
      ].filter(Boolean).join(' &nbsp;|&nbsp; ');
      return `<div class="fm-mem"><div class="fm-mem-name">${numL(i + 1)}. ${esc(or(m.name, tf('memberFallback', { n: numL(i + 1) })))}${m.isLeader ? starHtml : ''}</div>${sub ? `<div class="fm-mem-sub">${sub}</div>` : ''}</div>`;
    }).join('') : `<div class="fm-mem-sub">${esc(t('addMembersHint'))}</div>`;
    byHead = `${esc(t('submittedBy'))}:<span class="fm-count">(${esc(groupCountLabel())})</span>`;
    byBody = `<div class="fm-name">${esc(groupTitleLabel())}</div>
      <div class="fm-kvs">${kv(t('deptShortLabel'), formalDeptDisplay(state.department))}</div>
      <div class="fm-roster">${rosterHtml}</div>`;
  } else {
    byHead = `${esc(t('submittedBy'))}:`;
    byBody = `<div class="fm-name">${byName ? esc(byName) : '&nbsp;'}</div>
      <div class="fm-kvs">${kv(t('id'), byId)}${kv(t('roll'), state.roll)}${kv(t('deptShortLabel'), formalDeptDisplay(state.department))}</div>`;
  }

  // Submitted To
  const toLines = [state.toDesignation, state.deptTitle, state.isGuestTeacher ? state.toUniversity : '']
    .filter(has).map(v => `<div class="fm-line">${esc(v)}</div>`).join('');

  const subDate = fmtDate(state.dateSubmission) || '';

  return `
<div class="tpl-formal${isGroup ? ' fm-group' : ''}${isGroup && groupMembersData().length > 4 ? ' fm-many' : ''}${isBn ? ' fm-bn' : ''}" style="--fm-accent:${accent}">
  <div class="fm-head">
    ${logoHtml}
    <div class="fm-uni${uniCls}">${esc(uniDisp)}</div>
    ${has(state.deptTitle) ? `<div class="fm-sub">${esc(state.deptTitle)}</div>` : ''}
  </div>
  <div class="fm-doc">
    <div class="fm-eyebrow">${eyebrow}</div>
    <div class="fm-title${titleCls}">${esc(titleText)}</div>
  </div>
  <div class="fm-course">
    <div class="fm-lbl">${esc(t('fmCourseLabel'))}</div>
    <div class="fm-val fm-course-val">${courseVal}</div>
  </div>
  ${metaHtml ? `<div class="fm-meta">${metaHtml}</div>` : ''}
  <div class="fm-parties-wrap">
    <div class="fm-parties">
      <div class="fm-col fm-col-by">
        <div class="fm-party-h">${byHead}</div>
        ${byBody}
      </div>
      <div class="fm-col fm-col-to">
        <div class="fm-party-h">${esc(t('submittedTo'))}:</div>
        <div class="fm-name">${toName ? esc(toName) : '&nbsp;'}</div>
        <div class="fm-lines">${toLines}</div>
      </div>
    </div>
  </div>
  <div class="fm-foot">
    <div class="fm-lbl">${esc(t('dateOfSubmission'))}</div>
    <div class="fm-val fm-date">${subDate ? esc(subDate) : '&nbsp;'}</div>
  </div>
</div>`;
}
// Halo ("halo"): corner-arc cover — soft concentric arcs top-left / bottom-right,
// a diamond cluster and a dot grid as quiet corner ornaments, centred header with
// logo + institution, a hairline rule, then a big doc-type / number / title block
// above one rounded info card (Course | Submitted To, then Submitted By) and the
// submission date pinned to the foot.
// Assignment, Lab Report and Group Assignment share this one layout, in English and Bangla:
//   lab   -> adds "Date of Experiment" beside the submission date
//   group -> Submitted By becomes the group name + a two-column, leader-first roster
// The arc art is an inline SVG whose fill follows the palette (cardBar); the page
// background (plain / dotted / grid) is the app-wide "Background" option.
const HALO_ART_SVG = `<?xml version="1.0" encoding="utf-8"?><svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" version= "1.1" width="2382px" height="3369px" viewBox="-651 -596 2382 3369"><g id="layer1"><g style="fill:rgb(__HA_ARC__); fill-opacity:0.11764706; stroke-linejoin: miter"><path d="M-23.743896,-601.33246L-29.60608,-514.193Q-71.28406,-250.85089,-273.505,-92.96228Q-477.12537,64.798584,-753.05884,34.980835Q-1016.4013,-6.6971436,-1174.2896,-208.91821Q-1224.8788,-274.2849,-1257.6296,-351.36877L-1285.1559,-430.6167Q-1307.84,-512.41156,-1308.095,-601.33246Q-1301.2087,-874.21643,-1120.0061,-1055.4191Q-938.80347,-1236.6217,-665.91943,-1243.5079Q-393.03534,-1236.6217,-211.83276,-1055.4191Q-30.630127,-874.21643,-23.743896,-601.33246"/></g><g style="fill:rgb(__HA_ARC__); fill-opacity:0.11764706; stroke-linejoin: miter"><path d="M-109.894165,-601.3731L-114.97058,-525.9135Q-151.06213,-297.86896,-326.17792,-161.14331Q-502.50543,-24.528198,-741.4533,-50.349243Q-969.4979,-86.44092,-1106.2233,-261.55676Q-1150.0315,-318.16217,-1178.3926,-384.91376L-1202.2292,-453.53955Q-1221.8728,-524.3709,-1222.0936,-601.3731Q-1216.1304,-837.68066,-1059.2158,-994.59546Q-902.30115,-1151.5103,-665.9939,-1157.4735Q-429.68658,-1151.5103,-272.77203,-994.59546Q-115.8573,-837.68066,-109.894165,-601.3731"/></g><g style="fill:rgb(__HA_ARC__); fill-opacity:0.11764706; stroke-linejoin: miter"><path d="M-220.25458,-601.1532L-224.32416,-540.6605Q-253.2572,-357.84705,-393.63983,-248.23987Q-534.994,-138.72125,-726.5482,-159.42096Q-909.3617,-188.35406,-1018.96844,-328.737Q-1054.0876,-374.11505,-1076.8235,-427.62708L-1095.9323,-482.64142Q-1111.6797,-539.4238,-1111.8567,-601.1532Q-1107.0762,-790.5908,-981.28455,-916.3827Q-855.4929,-1042.1746,-666.05566,-1046.9551Q-476.61835,-1042.1746,-350.82666,-916.3827Q-225.03503,-790.5908,-220.25458,-601.1532"/></g><g style="fill:rgb(__HA_ARC__); fill-opacity:0.11764706; stroke-linejoin: miter"><path d="M-341.76062,-599.2556L-344.72632,-555.17126Q-365.81146,-421.9448,-468.1162,-342.068Q-571.1289,-262.25586,-710.7252,-277.34076Q-843.9517,-298.4259,-923.8283,-400.73083Q-949.42163,-433.8002,-965.9905,-472.7975L-979.91614,-512.8895Q-991.39215,-554.27,-991.5212,-599.2556Q-988.0374,-737.30945,-896.36597,-828.98096Q-804.6945,-920.65247,-666.64087,-924.1362Q-528.5873,-920.65247,-436.91583,-828.98096Q-345.2444,-737.30945,-341.76062,-599.2556"/></g><g style="fill:rgb(__HA_ARC__); fill-opacity:0.11764706; stroke-linejoin: miter"><path d="M-460.9776,-600.0653L-462.85608,-572.1428Q-476.2111,-487.7591,-541.00946,-437.1662Q-606.2562,-386.61423,-694.6746,-396.16885Q-779.0584,-409.5239,-829.6511,-474.3224Q-845.8616,-495.2682,-856.3561,-519.9684L-865.1764,-545.3622Q-872.4451,-571.572,-872.52686,-600.0653Q-870.32025,-687.5067,-812.25684,-745.5702Q-754.1935,-803.63367,-666.7522,-805.8403Q-579.31104,-803.63367,-521.24756,-745.5702Q-463.18417,-687.5067,-460.9776,-600.0653"/></g><g style="fill:rgb(__HA_ARC__); fill-opacity:0.11764706; stroke-linejoin: miter"><path d="M1153.986,2795.3198L1177.4624,2791.5056Q1366.3451,2761.4866,1431.052,2732.7568Q1502.9866,2707.5444,1588.6965,2629.144Q1656.4688,2565.809,1684.8442,2494.5566Q1712.2831,2433.654,1741.9915,2264.0522L1759.3811,2808.6677L1153.986,2795.3198"/></g><g style="fill:rgb(__HA_ARC__); fill-opacity:0.11764706; stroke-linejoin: miter"><path d="M1177.7565,2811.8508L1204.7861,2806.9304Q1384.0176,2775.7432,1469.4674,2745.4688Q1559.8988,2710.8757,1604.1638,2665.552Q1672.5542,2602.971,1702.8306,2525.9934Q1734.7474,2444.514,1765.762,2280.5833L1783.1516,2825.1987L1177.7565,2811.8508"/></g><g style="fill:rgb(__HA_ARC__); fill-opacity:0.11764706; stroke-linejoin: miter"><path d="M1218.2635,2841.0593L1257.6604,2830.045Q1424.7201,2783.207,1505.8226,2764.4812Q1525.8977,2759.245,1543.0035,2753.0408Q1595.1819,2733.0413,1634.8846,2695.6597Q1677.9216,2656.4766,1702.3057,2598.9426Q1713.6758,2572.8914,1725.0195,2540.6458L1806.2689,2309.7917L1823.6586,2854.4072L1218.2635,2841.0593"/></g><g style="fill:rgb(__HA_ARC__); fill-opacity:0.11764706; stroke-linejoin: miter"><path d="M1287.112,2858.861L1307.0135,2852.4556Q1417.3333,2816.804,1474.7543,2800.3748Q1507.7728,2790.4568,1592.741,2770.1443L1620.5922,2761.7166Q1654.4336,2749.75,1676.5981,2727.783Q1716.6099,2689.931,1736.0199,2598.2415Q1749.9583,2612.9524,1760.4841,2609.5042Q1771.2961,2607.2698,1786.4741,2578.587Q1808.6736,2539.4365,1875.1174,2327.5935L1769.0294,2819.349L1287.112,2858.861"/></g></g></svg>`;
function buildHaloArtUri(pal) {
  const svg = HALO_ART_SVG.replace(/__HA_ARC__/g, rgbTriple(safeHex(pal.cardBar, '#ee8b2b')));
  return "data:image/svg+xml;base64," + btoa(svg);
}
function buildHaloDiamondsSvg(color) {
  const d = (cx, cy, r) => `<path d="M${cx} ${cy - r}L${cx + r} ${cy}L${cx} ${cy + r}L${cx - r} ${cy}Z"/>`;
  return `<svg class="ha-deco ha-diamonds" viewBox="0 0 72 70" aria-hidden="true"><g fill="none" stroke="${color}" stroke-width="1.1" stroke-linejoin="round" opacity=".3">`
    + d(14, 14, 13) + d(38, 14, 13) + d(62, 14, 7)
    + d(14, 38, 12) + d(38, 38, 9) + d(62, 38, 6)
    + d(14, 60, 8) + d(38, 60, 6)
    + `</g></svg>`;
}
function buildHaloDotsSvg(color) {
  let dots = '';
  for (let r = 0; r < 5; r++) for (let c = 0; c < 5; c++) dots += `<circle cx="${4 + c * 18}" cy="${4 + r * 18}" r="2.2"/>`;
  return `<svg class="ha-deco ha-dots" viewBox="0 0 80 80" aria-hidden="true"><g fill="${color}" opacity=".24">${dots}</g></svg>`;
}
function renderHalo() {
  const pal = getPalette();
  const dt = getDocType();
  const accent = safeHex(pal.cardBar, '#ee8b2b');
  const isLab = state.docType === 'lab';
  const isGroup = isGroupDoc();
  const isBn = state.language === 'bn';
  const has = v => v != null && String(v).trim() !== '';
  const byName = or(state.byName || state.studentName, '');
  const byId = or(state.byId || state.studentId, '');
  const toName = or(state.toName, '');
  const uniDisp = String(or(state.universityName, t('universityNameFallback')));
  const noRaw = (state.assignmentNo || '').trim();
  const logoHtml = state.logoDataUrl
    ? `<img class="ha-logo-img" src="${state.logoDataUrl}" alt="Institution logo">` : '';
  const uniCls = uniDisp.length > 52 ? ' ha-uni-sm' : (uniDisp.length > 34 ? ' ha-uni-md' : '');

  // Doc-type eyebrow, big number, title
  const titleRaw = (state.assignmentTitle || '').trim();
  const titleText = titleRaw || tf('titleGoesHere', { word: dt.word });
  const titleCls = (titleRaw ? '' : ' ha-ph')
    + (titleText.length > 110 ? ' ha-title-sm' : (titleText.length > 64 ? ' ha-title-md' : ''))
    + (noRaw ? '' : ' ha-title-solo');
  const noHtml = noRaw ? `<div class="ha-no">${esc(t('fmNoShort'))} ${esc(noRaw)}</div>` : '';

  // Course (left of the top row)
  const code = (state.courseCode || '').trim();
  const ctitle = (state.courseTitle || '').trim();
  const courseHtml = `
      <div class="ha-lbl">${esc(t('course'))}</div>
      <div class="ha-strong${ctitle ? '' : ' ha-ph'}">${esc(ctitle || t('coverCourseTitleFallback'))}</div>
      ${code ? `<div class="ha-line">${esc(code)}</div>` : ''}`;

  // Submitted To (right of the top row)
  const toLines = [state.toDesignation, state.deptTitle, state.isGuestTeacher ? state.toUniversity : '']
    .filter(has).map(v => `<div class="ha-line">${esc(v)}</div>`).join('');
  const toHtml = `
      <div class="ha-lbl">${esc(t('submittedTo'))}</div>
      <div class="ha-strong">${toName ? esc(toName) : '&nbsp;'}</div>
      ${toLines}`;

  // Submitted By
  const join = a => a.filter(Boolean).join(' <span class="ha-dot">&middot;</span> ');
  const kv = (k, v) => has(v) ? `${esc(k)}: ${esc(v)}` : '';
  const batchSem = join([kv(t('batch'), state.section), kv(t('semester'), state.semester)]);
  let byHtml;
  if (isGroup) {
    const members = groupMembersLeaderFirst();
    const star = `<svg class="ha-star" viewBox="0 0 24 24" role="img" aria-label="${esc(t('gmLeaderLabel'))}"><path d="M12.00 1.20 L15.47 7.83 L22.84 9.08 L17.61 14.42 L18.70 21.82 L12.00 18.50 L5.30 21.82 L6.39 14.42 L1.16 9.08 L8.53 7.83Z" fill="currentColor"/></svg>`;
    const roster = members.length ? members.map((m, i) => {
      const sub = join([kv(t('id'), m.studentId), kv(t('roll'), m.roll)]);
      return `<div class="ha-mem"><div class="ha-mem-name">${numL(i + 1)}. ${esc(or(m.name, tf('memberFallback', { n: numL(i + 1) })))}${m.isLeader ? star : ''}</div>${sub ? `<div class="ha-mem-sub">${sub}</div>` : ''}</div>`;
    }).join('') : `<div class="ha-mem-sub">${esc(t('addMembersHint'))}</div>`;
    const groupMeta = join([has(state.department) ? esc(state.department) : '', batchSem]);
    byHtml = `
      <div class="ha-lbl">${esc(t('submittedBy'))}<span class="ha-count">(${esc(groupCountLabel())})</span></div>
      <div class="ha-strong">${esc(groupTitleLabel())}</div>
      ${groupMeta ? `<div class="ha-line">${groupMeta}</div>` : ''}
      <div class="ha-roster">${roster}</div>`;
  } else {
    const idRoll = join([kv(t('id'), byId), kv(t('roll'), state.roll)]);
    byHtml = `
      <div class="ha-lbl">${esc(t('submittedBy'))}</div>
      <div class="ha-strong">${byName ? esc(byName) : '&nbsp;'}</div>
      ${idRoll ? `<div class="ha-line">${idRoll}</div>` : ''}
      ${has(state.department) ? `<div class="ha-line">${esc(state.department)}</div>` : ''}
      ${batchSem ? `<div class="ha-line">${batchSem}</div>` : ''}`;
  }

  // Dates
  const expDate = isLab ? (fmtDate(state.dateExperiment) || '') : '';
  const subDate = fmtDate(state.dateSubmission) || '';
  const dateItem = (label, val) => `<div class="ha-date-item"><div class="ha-lbl ha-lbl-c">${esc(label)}</div><div class="ha-date">${val ? esc(val) : '&nbsp;'}</div></div>`;
  const dateHtml = (isLab && expDate ? dateItem(t('dateOfExperimentLabel'), expDate) : '') + dateItem(t('haSubmissionDate'), subDate);

  return `
<div class="tpl-halo${isGroup ? ' ha-group' : ''}${isGroup && groupMembersData().length > 6 ? ' ha-many' : ''}${isBn ? ' ha-bn' : ''}" style="--ha-accent:${accent}">
  <img class="ha-art" src="${buildHaloArtUri(pal)}" alt="">
  ${buildHaloDiamondsSvg(accent)}
  ${buildHaloDotsSvg(accent)}
  <div class="ha-head">
    ${logoHtml}
    <div class="ha-uni${uniCls}">${esc(uniDisp)}</div>
    ${has(state.deptTitle) ? `<div class="ha-sub">${esc(state.deptTitle)}</div>` : ''}
  </div>
  <div class="ha-mid">
    <div class="ha-doc">
      <div class="ha-eyebrow">${esc(dt.word)}</div>
      ${noHtml}
      <div class="ha-title${titleCls}">${esc(titleText)}</div>
    </div>
    <div class="ha-card">
      ${isGroup ? `
      <div class="ha-row ha-row-top">
        <div class="ha-cell">${courseHtml}</div>
        <div class="ha-cell">${toHtml}</div>
      </div>
      <div class="ha-row ha-row-by">${byHtml}</div>` : `
      <div class="ha-row ha-row-top">
        <div class="ha-cell">${courseHtml}</div>
        <div class="ha-cell">${byHtml}</div>
      </div>
      <div class="ha-row ha-row-to">${toHtml}</div>`}
    </div>
  </div>
  <div class="ha-foot">${dateHtml}</div>
</div>`;
}
