// Spectrum ("spectrum"): left-aligned minimal cover with a bar-chart skyline fading
// up from the foot of the page. Header = logo + institution (+ department line), hairline,
// small doc-type eyebrow over a huge "No. 01", then a hairline-ruled info grid and the
// submission date. Assignment, Lab Report and Group Assignment share this one layout,
// in English and Bangla:
//   assignment -> Course | Submitted By, with Submitted To under the course
//   lab        -> adds "Date of Experiment" beside the submission date
//   group      -> Course | Submitted To on top, then a full-width Submitted By block
//                 (group name + single-column, leader-first roster)
// The skyline art is an inline SVG whose bars follow the palette (cardBar), caps are a
// lighter tint of it; the page background (plain / dotted / grid) is the app-wide option.
function buildSpectrumArtUri(pal) {
  const hex = safeHex(pal.cardBar, '#ee8b2b');
  const n = parseInt(hex.slice(1), 16);
  const mix = k => [n >> 16 & 255, n >> 8 & 255, n & 255].map(v => Math.round(v * (1 - k) + 255 * k)).join(',');
  const svg = SPECTRUM_ART_SVG
    .replace(/__SP_BAR__/g, rgbTriple(hex))
    .replace(/__SP_CAP__/g, mix(0.64));
  return "data:image/svg+xml;base64," + btoa(svg);
}
function renderSpectrum() {
  const pal = getPalette();
  const dt = getDocType();
  const accent = safeHex(pal.cardBar, '#ee8b2b');
  const isLab = state.docType === 'lab';
  const isGroup = isGroupDoc();
  const isBn = state.language === 'bn';
  const has = v => v != null && String(v).trim() !== '';
  const byName = or(state.byName || state.studentName, '');
  const byId = or(state.byId || state.studentId, '');
  const toName = or(state.toName, '');
  const uniDisp = String(or(state.universityName, t('universityNameFallback')));
  const noRaw = (state.assignmentNo || '').trim();
  const logoHtml = state.logoDataUrl
    ? `<img class="sp-logo-img" src="${state.logoDataUrl}" alt="Institution logo">` : '';
  const uniCls = uniDisp.length > 52 ? ' sp-uni-sm' : (uniDisp.length > 34 ? ' sp-uni-md' : '');

  // Eyebrow, big number, title
  const titleRaw = (state.assignmentTitle || '').trim();
  const titleText = titleRaw || tf('titleGoesHere', { word: dt.word });
  const titleCls = (titleRaw ? '' : ' sp-ph')
    + (titleText.length > 110 ? ' sp-title-sm' : (titleText.length > 64 ? ' sp-title-md' : ''))
    + (noRaw ? '' : ' sp-title-solo');
  const noHtml = noRaw ? `<div class="sp-no">${esc(t('fmNoShort'))} ${esc(noRaw)}</div>` : '';

  // Course
  const code = (state.courseCode || '').trim();
  const ctitle = (state.courseTitle || '').trim();
  const courseHtml = `
      <div class="sp-lbl">${esc(t('course'))}</div>
      <div class="sp-strong${ctitle ? '' : ' sp-ph'}">${esc(ctitle || t('coverCourseTitleFallback'))}</div>
      ${code ? `<div class="sp-line">${esc(code)}</div>` : ''}`;

  // Submitted To
  const toLines = [state.toDesignation, state.isGuestTeacher ? state.toUniversity : '']
    .filter(has).map(v => `<div class="sp-line">${esc(v)}</div>`).join('');
  const toHtml = `
      <div class="sp-lbl">${esc(t('submittedTo'))}</div>
      <div class="sp-strong">${toName ? esc(toName) : '&nbsp;'}</div>
      ${toLines}`;

  // Submitted By
  const join = a => a.filter(Boolean).join(' <span class="sp-dot">&middot;</span> ');
  const kv = (k, v) => has(v) ? `${esc(k)}: ${esc(v)}` : '';
  const batchSem = join([kv(t('batch'), state.section), kv(t('semester'), state.semester)]);
  let byHtml;
  if (isGroup) {
    const members = groupMembersLeaderFirst();
    const star = `<svg class="sp-star" viewBox="0 0 24 24" role="img" aria-label="${esc(t('gmLeaderLabel'))}"><path d="M12.00 1.20 L15.47 7.83 L22.84 9.08 L17.61 14.42 L18.70 21.82 L12.00 18.50 L5.30 21.82 L6.39 14.42 L1.16 9.08 L8.53 7.83Z" fill="currentColor"/></svg>`;
    const roster = members.length ? members.map((m, i) => {
      const sub = join([kv(t('id'), m.studentId), kv(t('roll'), m.roll)]);
      return `<div class="sp-mem"><div class="sp-mem-name">${numL(i + 1)}. ${esc(or(m.name, tf('memberFallback', { n: numL(i + 1) })))}${m.isLeader ? star : ''}</div><div class="sp-mem-sub">${sub}</div></div>`;
    }).join('') : `<div class="sp-mem"><div class="sp-mem-sub">${esc(t('addMembersHint'))}</div></div>`;
    const groupMeta = join([has(state.department) ? esc(state.department) : '', batchSem]);
    byHtml = `
      <div class="sp-lbl">${esc(t('submittedBy'))}<span class="sp-count">(${esc(groupCountLabel())})</span></div>
      <div class="sp-strong">${esc(groupTitleLabel())}</div>
      ${groupMeta ? `<div class="sp-line">${groupMeta}</div>` : ''}
      <div class="sp-roster">${roster}</div>
      ${members.some(m => m.isLeader) ? `<div class="sp-legend">${star}<span>${esc(t('gmLeaderLabel'))}</span></div>` : ''}`;
  } else {
    const idRoll = join([kv(t('id'), byId), kv(t('roll'), state.roll)]);
    byHtml = `
      <div class="sp-lbl">${esc(t('submittedBy'))}</div>
      <div class="sp-strong">${byName ? esc(byName) : '&nbsp;'}</div>
      ${idRoll ? `<div class="sp-line">${idRoll}</div>` : ''}
      ${has(state.department) ? `<div class="sp-line">${esc(state.department)}</div>` : ''}
      ${batchSem ? `<div class="sp-line">${batchSem}</div>` : ''}`;
  }

  // Dates
  const expDate = isLab ? (fmtDate(state.dateExperiment) || '') : '';
  const subDate = fmtDate(state.dateSubmission) || '';
  const dateItem = (label, val) => `<div class="sp-date-item"><div class="sp-lbl">${esc(label)}</div><div class="sp-date">${val ? esc(val) : '&nbsp;'}</div></div>`;
  const dateHtml = dateItem(t('haSubmissionDate'), subDate) + (isLab && expDate ? dateItem(t('dateOfExperimentLabel'), expDate) : '');

  return `
<div class="tpl-spectrum${isGroup ? ' sp-group' : ''}${isBn ? ' sp-bn' : ''}" style="--sp-accent:${accent}">
  <img class="sp-art" src="${buildSpectrumArtUri(pal)}" alt="">
  <div class="sp-head">
    ${logoHtml}
    <div class="sp-head-text">
      <div class="sp-uni${uniCls}">${esc(uniDisp)}</div>
      ${has(state.deptTitle) ? `<div class="sp-sub">${esc(state.deptTitle)}</div>` : ''}
    </div>
  </div>
  <div class="sp-doc">
    <div class="sp-eyebrow">${esc(dt.word)}</div>
    ${noHtml}
    <div class="sp-title${titleCls}">${esc(titleText)}</div>
  </div>
  ${isGroup ? `
  <div class="sp-sec sp-grid">
    <div class="sp-cell">${courseHtml}</div>
    <div class="sp-cell">${toHtml}</div>
  </div>
  <div class="sp-sec">${byHtml}</div>` : `
  <div class="sp-sec sp-grid">
    <div class="sp-cell">${courseHtml}<div class="sp-gap"></div>${toHtml}</div>
    <div class="sp-cell">${byHtml}</div>
  </div>`}
  <div class="sp-sec sp-dates">${dateHtml}</div>
</div>`;
}
// Brutalist ("brutalist"): oversized-number cover. Spaced doc-type eyebrow over a thick
// accent bar, a small square + "NO." label and a giant bold number, then (pushed to the
// foot of the page) a ruled Course | Submitted By block and a footer with the submission
// date on the left and logo + institution on the right. Background art is pure CSS: a pale
// slanted wash in the top-right corner, a hairline and the institution name as a rotated,
// cropped watermark on the right edge - all tinted from the palette (cardBar).
//   assignment -> teacher sits under the course (no label), e.g. "Dr. X [INIT]"
//   lab        -> adds "Date of Experiment" beside the submission date
//   group      -> Course (30%) | Submitted By (70%): group name, then the roster beneath it in the same right column; number shrinks
function renderBrutalist() {
  const pal = getPalette();
  const dt = getDocType();
  const accent = safeHex(pal.cardBar, '#ee8b2b');
  const isLab = state.docType === 'lab';
  const isGroup = isGroupDoc();
  const isBn = state.language === 'bn';
  const has = v => v != null && String(v).trim() !== '';
  const byName = or(state.byName || state.studentName, '');
  const byId = or(state.byId || state.studentId, '');
  const toName = or(state.toName, '');
  const uniDisp = String(or(state.universityName, t('universityNameFallback')));
  const noRaw = (state.assignmentNo || '').trim();
  const members = isGroup ? groupMembersLeaderFirst() : [];
  const many = isGroup && members.length > 5;
  const logoHtml = state.logoDataUrl
    ? `<img class="bt-logo-img" src="${state.logoDataUrl}" alt="Institution logo">` : '';
  const uniCls = uniDisp.length > 52 ? ' bt-uni-sm' : (uniDisp.length > 34 ? ' bt-uni-md' : '');
  // Rotated watermark: shrink the type so the whole name fits the page height
  const wmFs = Math.max(24, Math.min(54, Math.floor(790 / (Math.max(uniDisp.length, 1) * 0.76))));

  // Eyebrow, number, title
  const titleRaw = (state.assignmentTitle || '').trim();
  const titleText = titleRaw || tf('titleGoesHere', { word: dt.word });
  const titleCls = (titleRaw ? '' : ' bt-ph')
    + (titleText.length > 110 ? ' bt-title-sm' : (titleText.length > 64 ? ' bt-title-md' : ''))
    + (noRaw ? '' : ' bt-title-solo');
  const digits = [...noRaw].length;
  let noFs = digits <= 2 ? 220 : (digits === 3 ? 170 : (digits === 4 ? 128 : 92));
  if (isGroup) noFs = Math.round(noFs * (many ? 0.5 : 0.68));
  const noHtml = noRaw ? `
    <div class="bt-no-row"><span class="bt-sq"></span><span class="bt-no-lbl">${esc(t('fmNoShort'))}</span></div>
    <div class="bt-no" style="font-size:${noFs}px">${esc(noRaw)}</div>` : '';

  // Course + teacher (teacher's trailing [INITIALS] is set bold)
  const code = (state.courseCode || '').trim();
  const ctitle = (state.courseTitle || '').trim();
  const toBold = s => esc(s).replace(/\[([^\]]+)\]\s*$/, '<b>[$1]</b>');
  const toLines = [state.toDesignation, state.isGuestTeacher ? state.toUniversity : '']
    .filter(has).map(v => `<div class="bt-line">${esc(v)}</div>`).join('');
  const courseHtml = `
      <div class="bt-lbl">${esc(t('course'))}</div>
      <div class="bt-strong${ctitle ? '' : ' bt-ph'}">${esc(ctitle || t('coverCourseTitleFallback'))}</div>
      ${code ? `<div class="bt-line">${esc(code)}</div>` : ''}
      ${has(toName) ? `<div class="bt-line">${toBold(toName)}</div>` : ''}${toLines}`;

  // Submitted By
  const join = a => a.filter(Boolean).join(' <span class="bt-dot">&middot;</span> ');
  const kv = (k, v) => has(v) ? `${esc(k)} ${esc(v)}` : '';   // label + value ("Batch 17")
  const bare = v => has(v) ? esc(v) : '';                          // value only
  const batchSem = join([kv(t('batch'), state.section), bare(state.semester)]);
  let byHtml = '';
  let rosterHtml = '';
  if (isGroup) {
    const star = `<svg class="bt-star" viewBox="0 0 24 24" role="img" aria-label="${esc(t('gmLeaderLabel'))}"><path d="M12.00 1.20 L15.47 7.83 L22.84 9.08 L17.61 14.42 L18.70 21.82 L12.00 18.50 L5.30 21.82 L6.39 14.42 L1.16 9.08 L8.53 7.83Z" fill="currentColor"/></svg>`;
    const rows = members.length ? members.map((m, i) => {
      const sub = join([bare(m.studentId), kv(t('roll'), m.roll)]);
      return `<div class="bt-mem"><div class="bt-mem-name">${numL(i + 1)}. ${esc(or(m.name, tf('memberFallback', { n: numL(i + 1) })))}${m.isLeader ? star : ''}</div><div class="bt-mem-sub">${sub}</div></div>`;
    }).join('') : `<div class="bt-mem"><div class="bt-mem-sub">${esc(t('addMembersHint'))}</div></div>`;
    const groupMeta = join([has(state.department) ? esc(state.department) : '', batchSem]);
    byHtml = `
      <div class="bt-lbl">${esc(t('submittedBy'))}<span class="bt-count">(${esc(groupCountLabel())})</span></div>
      <div class="bt-strong">${esc(groupTitleLabel())}</div>
      ${groupMeta ? `<div class="bt-line">${groupMeta}</div>` : ''}`;
    rosterHtml = `
    <div class="bt-roster">${rows}</div>
    ${members.some(m => m.isLeader) ? `<div class="bt-legend">${star}<span>${esc(t('gmLeaderLabel'))}</span></div>` : ''}`;
  } else {
    const idRoll = join([bare(byId), kv(t('roll'), state.roll)]);
    byHtml = `
      <div class="bt-lbl">${esc(t('submittedBy'))}</div>
      <div class="bt-strong">${byName ? esc(byName) : '&nbsp;'}</div>
      ${idRoll ? `<div class="bt-line">${idRoll}</div>` : ''}
      ${has(state.department) ? `<div class="bt-line">${esc(state.department)}</div>` : ''}
      ${batchSem ? `<div class="bt-line">${batchSem}</div>` : ''}`;
  }

  // Dates
  const expDate = isLab ? (fmtDate(state.dateExperiment) || '') : '';
  const subDate = fmtDate(state.dateSubmission) || '';
  const dateItem = (label, val) => `<div class="bt-date-item"><div class="bt-lbl">${esc(label)}</div><div class="bt-date">${val ? esc(val) : '&nbsp;'}</div></div>`;
  const dateHtml = dateItem(t('haSubmissionDate'), subDate) + (isLab && expDate ? dateItem(t('dateOfExperimentLabel'), expDate) : '');

  const rgba = a => hexToRgba(accent, a);
  return `
<div class="tpl-brutalist${isGroup ? ' bt-group' : ''}${many ? ' bt-many' : ''}${isBn ? ' bt-bn' : ''}" style="--bt-accent:${accent};--bt-wash:${rgba(0.06)};--bt-bar:${rgba(0.38)};--bt-sq:${rgba(0.42)};--bt-line-c:${rgba(0.24)};--bt-wm:${rgba(0.10)}">
  <div class="bt-wash"></div>
  <div class="bt-vline"></div>
  <div class="bt-wm" style="font-size:${wmFs}px">${esc(uniDisp)}</div>
  <div class="bt-top">
    <div class="bt-eyebrow">${esc(dt.word)}</div>
    <div class="bt-bar"></div>
    ${noHtml}
    <div class="bt-title${titleCls}">${esc(titleText)}</div>
  </div>
  <div class="bt-info">
    <div class="bt-grid">
      <div class="bt-cell">${courseHtml}</div>
      <div class="bt-cell bt-cell-by">${byHtml}${rosterHtml}</div>
    </div>
  </div>
  <div class="bt-foot">
    <div class="bt-dates">${dateHtml}</div>
    <div class="bt-brand">
      ${logoHtml}
      <div class="bt-brand-text">
        <div class="bt-uni${uniCls}">${esc(uniDisp)}</div>
        ${has(state.deptTitle) ? `<div class="bt-sub">${esc(state.deptTitle)}</div>` : ''}
      </div>
    </div>
  </div>
</div>`;
}
const RENDERERS = { cards: renderCards, emblem: renderEmblem, spring: renderspring, dusk: renderDusk, circles: renderCircles, brief: renderBrief, ledger: renderLedger, sigil: renderSigil, voltalic: rendervoltalic, obliqua: renderObliqua, banner: renderBanner, formal: renderFormal, halo: renderHalo, spectrum: renderSpectrum, brutalist: renderBrutalist };